/**
 * Resolves a slug to its live organization, honoring retired slugs still
 * within their hold window (see ADR 0005) — every lookup of a workspace by
 * slug, including the session layer, must go through this rule.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const holder = await findSlugRetirement(slug);
  if (!holder || !isWithinSlugHold(holder.retiredAt)) return null;

  const org = await findOrgById(brandId<OrgId>(holder.orgId));
  return org && org.archivedAt === null ? org : null;
}

/** Any org — live or archived — currently holding `slug` as its slug column. */
export async function findOrgByCurrentSlugIncludingArchived(
  slug: string,
): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  return row ? toOrganization(row) : null;
}

/** The most recent retirement of `slug`, by any org, regardless of hold expiry. */
export async function findSlugRetirement(
  slug: string,
): Promise<{ orgId: string; retiredAt: string } | null> {
  const row = getDb()
    .select()
    .from(organizationSlugHistory)
    .where(eq(organizationSlugHistory.slug, slug))
    .orderBy(desc(organizationSlugHistory.retiredAt))
    .get();
  return row ? { orgId: row.orgId, retiredAt: row.retiredAt } : null;
}

/** True while `retiredAt` is still inside `ORG_SLUG_HOLD_DAYS` of now. */
export function isWithinSlugHold(retiredAt: string): boolean {
  const releaseMs =
    new Date(retiredAt).getTime() + ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000;
  return Date.now() < releaseMs;
}

/** Retires `slug` on behalf of `orgId`, starting its hold window. */
export async function retireOrgSlug(
  orgId: OrgId,
  slug: string,
  retiredAt: string,
): Promise<void> {
  getDb()
    .insert(organizationSlugHistory)
    .values({ id: newId(), orgId, slug, retiredAt })
    .run();
}

/** Un-retires a slug the given org previously held, e.g. when renaming back to it. */
export async function releaseRetiredSlug(
  orgId: OrgId,
  slug: string,
): Promise<void> {
  getDb()
    .delete(organizationSlugHistory)
    .where(
      and(
        eq(organizationSlugHistory.orgId, orgId),
        eq(organizationSlugHistory.slug, slug),
      ),
    )
    .run();
}

/** Writes the new slug column directly, with no availability check of its own. */
export async function setOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set({ slug, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

