/**
 * Changes a workspace's URL slug. The old slug is retired, not released: it
 * keeps resolving for `ORG_SLUG_HOLD_DAYS` days (see ADR 0005) and nobody else
 * can take it until then, while a slug the same workspace retired itself is
 * available to it again immediately. A collision is refused, never suffixed —
 * renaming is a deliberate choice — and renaming to the current slug is a
 * no-op that changes and publishes nothing.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (input.slug === org.slug) {
    return org;
  }

  assertValidSlug(input.slug);

  const currentHolder = await orgRepo.findOrgByCurrentSlugIncludingArchived(
    input.slug,
  );
  if (currentHolder && currentHolder.id !== org.id) {
    throw new InvalidSlugError(input.slug, "is taken");
  }

  const retirement = await orgRepo.findSlugRetirement(input.slug);
  const retiredByOther =
    retirement !== null &&
    retirement.orgId !== org.id &&
    orgRepo.isWithinSlugHold(retirement.retiredAt);
  if (retiredByOther) {
    throw new InvalidSlugError(input.slug, "is taken");
  }

  if (retirement !== null && retirement.orgId === org.id) {
    await orgRepo.releaseRetiredSlug(org.id, input.slug);
  }

  const previousSlug = org.slug;
  await orgRepo.retireOrgSlug(org.id, previousSlug, toIsoTimestamp(new Date()));
  const updated = await orgRepo.setOrgSlug(org.id, input.slug);

  await emit("organization.slug_changed", {
    ...envelope(org.id, actor.userId),
    from: previousSlug,
    to: input.slug,
  });

  return updated;
}

